@namespace      github.com/improved/dark-instagram-gruvbox
@author         Gruvbox edition — variable-only recolor, no filter cascade
@description    Gruvbox dark theme for Instagram. No broad filter:invert() — post images and media are never affected.
@version        4.1.0
@license        CC BY-NC-SA 4.0
@preprocessor   uso
@advanced text feed "Feed width (0-50%)" 50%
==/UserStyle== */

@-moz-document domain('instagram.com') {
    @import url("https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@300;400;500;600;700&display=swap");

    /* ============================================================
    SECTION 1: INSTAGRAM CORE DESIGN TOKENS — GRUVBOX DARK
    ============================================================ */

    html,
    body,
    div,
    nav,
    article,
    section {

        /*
        NOTE: All --ig-* variables MUST remain as bare "r, g, b" triplets.
        Instagram's own CSS consumes them as: rgb(var(--ig-primary-background))
        Converting them to hex would silently break all Instagram UI colours.
        The hex equivalents are shown in comments for easy reference only.
        */

        /* Backgrounds */
        --ig-primary-background:     40,  40,  40 !important;   /* #282828  bg0     */
        --ig-secondary-background:   29,  32,  33 !important;   /* #1d2021  bg0_h   */
        --ig-elevated-background:    60,  56,  54 !important;   /* #3c3836  bg1     */
        --ig-highlight-background:   80,  73,  69 !important;   /* #504945  bg2     */
        --ig-full-screen-background: 60,  56,  54 !important;   /* #3c3836  bg1     */
        --ig-banner-background:      40,  40,  40 !important;   /* #282828  bg0     */

        /* Text */
        --ig-primary-text:   235, 219, 178 !important;          /* #ebdbb2  fg1     */
        --ig-secondary-text: 189, 174, 147 !important;          /* #bdae93  fg3     */
        --ig-tertiary-text:  168, 153, 132 !important;          /* #a89984  fg4     */
        --ig-text-on-color:  251, 241, 199 !important;          /* #fbf1c7  fg0     */

        /* Separators / Borders */
        --ig-separator:          60,  56,  54 !important;       /* #3c3836  bg1     */
        --ig-elevated-separator: 80,  73,  69 !important;       /* #504945  bg2     */
        --ig-stroke:            102,  92,  84 !important;       /* #665c54  bg3     */
        --ig-focus-stroke:      124, 111, 100 !important;       /* #7c6f64  bg4     */

        /* Interactive / Accent */
        --ig-primary-button:   131, 165, 152 !important;        /* #83a598  bright blue   */
        --ig-secondary-button: 189, 174, 147 !important;        /* #bdae93  fg3           */
        --ig-link:             131, 165, 152 !important;        /* #83a598  bright blue   */

        /* Status */
        --ig-badge:                    251,  73,  52 !important; /* #fb4934  bright red    */
        --ig-live-badge:               214,  93,  14 !important; /* #d65d0e  orange        */
        --ig-close-friends-refreshed:  142, 192, 124 !important; /* #8ec07c  bright aqua   */
        --ig-error-or-destructive:     251,  73,  52 !important; /* #fb4934  bright red    */
        --ig-success:                  184, 187,  38 !important; /* #b8bb26  bright green  */
        --ig-subscribers-only:         211, 134, 155 !important; /* #d3869b  bright purple */
        --ig-temporary-highlight:      250, 189,  47 !important; /* #fabd2f  bright yellow */

        /* Brand */
        --ig-facebook-blue: 131, 165, 152 !important;           /* #83a598  bright blue   */

        /* Modals */
        --modal-backdrop-dark:    rgba(29, 32, 33, .92) !important;  /* #1d2021  bg0_h */
        --modal-backdrop-default: rgba(29, 32, 33, .75) !important;  /* #1d2021  bg0_h */
        --modal-border-radius: 12px !important;
        --modal-padding:       16px !important;
        --modal-z-index:       100 !important;
        --tos-box-shadow:      0, 0, 0 !important;               /* #000000        */

        /* Misc */
        --web-always-black:       0,   0,   0 !important;        /* #000000        */
        --web-always-white:     251, 241, 199 !important;        /* #fbf1c7  fg0   */
        --web-overlay-on-media:  40,  40,  40 !important;        /* #282828  bg0   */
        --web-secondary-action: 131, 165, 152 !important;        /* #83a598  bright blue */
        --post-separator:        60,  56,  54 !important;        /* #3c3836  bg1   */
        --post-step-indicator:  168, 153, 132 !important;        /* #a89984  fg4   */
        --photo: 600px;

        /* Colour palette tokens */
        --orange-5: #fe8019;   /* bright orange */
        --pink-5:   #d3869b;   /* bright purple */
        --purple-5: #b16286;   /* purple        */
        --red-4:    #fb4934;   /* bright red    */
        --red-5:    #cc241d;   /* red           */
        --red-6:    #9d0006;   /* dark red      */
        --red-7:    #79000a;
        --yellow-5: #fabd2f;   /* bright yellow */
        --w1:       235, 219, 178;                    /* #ebdbb2  fg1   */

        /* ------------------------------------------------------------------
        INSTAGRAM RUNTIME OBFUSCATED VARIABLES — GRUVBOX MAPPED
        Same rule applies: must stay as r, g, b triplets with !important.
        ------------------------------------------------------------------ */

        --fe0: 131, 165, 152 !important;     /* #83a598  username links      → bright blue   */
        --d69: 131, 165, 152 !important;     /* #83a598  follow button       → bright blue   */
        --f24: 131, 165, 152 !important;     /* #83a598  primary action      → bright blue   */
        --b86: 184, 187,  38 !important;     /* #b8bb26  success green       → bright green  */
        --i30: 251,  73,  52 !important;     /* #fb4934  error red           → bright red    */
        --c37: 251,  73,  52 !important;     /* #fb4934                                      */
        --eac: 251,  73,  52 !important;     /* #fb4934                                      */
        --fa7: 250, 189,  47 !important;     /* #fabd2f  accent yellow       → bright yellow */
        --e62: 250, 189,  47 !important;     /* #fabd2f                                      */
        --jbb: 131, 165, 152 !important;     /* #83a598  facebook blue       → bright blue   */
        --b2f: 211, 134, 155 !important;     /* #d3869b  purple              → bright purple */

        --jb7:  60,  56,  54 !important;     /* #3c3836  DM bubble bg        → bg1           */
        --jd9: 235, 219, 178 !important;     /* #ebdbb2  DM bubble text      → fg1           */
        --cdd: 213, 196, 161 !important;     /* #d5c4a1  DM secondary text   → fg2           */

        --i1d: 235, 219, 178 !important;     /* #ebdbb2  primary text        → fg1           */
        --d20: 189, 174, 147 !important;     /* #bdae93  secondary text      → fg3           */
        --eca:  50,  48,  47 !important;     /* #32302f  inverse surface     → bg0_s         */

        --f75: 189, 174, 147 !important;     /* #bdae93  username / likes    → fg3           */
        --j64: 213, 196, 161 !important;     /* #d5c4a1  like count          → fg2           */
        --f52: 168, 153, 132 !important;     /* #a89984  time labels         → fg4           */
        --ie3: 168, 153, 132 !important;     /* #a89984                                      */

        --ba8: 124, 111, 100 !important;     /* #7c6f64  muted icons         → bg4           */
        --c8c: 124, 111, 100 !important;     /* #7c6f64                                      */

        --e22:  80,  73,  69 !important;     /* #504945  mid bg              → bg2           */
        --edc:  80,  73,  69 !important;     /* #504945                                      */

        --b38: 102,  92,  84 !important;     /* #665c54  borders             → bg3           */
        --b6a: 102,  92,  84 !important;     /* #665c54                                      */
        --ca6: 102,  92,  84 !important;     /* #665c54                                      */
        --ce3: 102,  92,  84 !important;     /* #665c54  spacer              → bg3           */

        --bb2:  29,  32,  33 !important;     /* #1d2021  deepest bg          → bg0_h         */
        --a97:  20,  22,  23 !important;     /* #141617                                      */

        --b3f:  40,  40,  40 !important;     /* #282828  main background     → bg0           */
        --d62:  40,  40,  40 !important;     /* #282828                                      */
        --a72:  40,  40,  40 !important;     /* #282828                                      */
        --h1d:  40,  40,  40 !important;     /* #282828                                      */
        --de5:  40,  40,  40 !important;     /* #282828                                      */

        --d87:  40,  40,  40 !important;     /* #282828  header backgrounds  → bg0           */
        --f23:  40,  40,  40 !important;     /* #282828                                      */
    }


    /* ============================================================
    SECTION 2: FDS TOKENS — GRUVBOX MAPPED
    ============================================================ */

    :root,
    .__fb-light-mode {
        /* Alpha tokens — keep as-is, used for shadows/overlays */
        --fds-black-alpha-05: rgba(0, 0, 0, 0.05);
        --fds-black-alpha-10: rgba(0, 0, 0, 0.1);
        --fds-black-alpha-15: rgba(0, 0, 0, 0.15);
        --fds-black-alpha-20: rgba(0, 0, 0, 0.2);
        --fds-black-alpha-30: rgba(0, 0, 0, 0.3);
        --fds-black-alpha-40: rgba(0, 0, 0, 0.4);
        --fds-black-alpha-50: rgba(0, 0, 0, 0.5);
        --fds-black-alpha-60: rgba(0, 0, 0, 0.6);
        --fds-black-alpha-80: rgba(0, 0, 0, 0.8);
        --fds-white-alpha-05: rgba(235, 219, 178, 0.05);
        --fds-white-alpha-10: rgba(235, 219, 178, 0.1);
        --fds-white-alpha-20: rgba(235, 219, 178, 0.2);
        --fds-white-alpha-30: rgba(235, 219, 178, 0.3);
        --fds-white-alpha-40: rgba(235, 219, 178, 0.4);
        --fds-white-alpha-50: rgba(235, 219, 178, 0.5);
        --fds-white-alpha-60: rgba(235, 219, 178, 0.6);
        --fds-white-alpha-80: rgba(235, 219, 178, 0.8);

        /* Solid tokens → gruvbox bg/fg scale */
        --fds-black:          #1d2021;   /* bg0_h */
        --fds-white:          #282828;   /* bg0   */
        --fds-primary-text:   #ebdbb2;   /* fg1   */
        --fds-primary-icon:   #ebdbb2;
        --fds-gray-00:        #1d2021;
        --fds-gray-05:        #282828;
        --fds-gray-10:        #32302f;
        --fds-gray-20:        #3c3836;
        --fds-gray-25:        #504945;
        --fds-gray-30:        #665c54;
        --fds-gray-45:        #7c6f64;
        --fds-gray-70:        #928374;
        --fds-gray-80:        #a89984;
        --fds-gray-90:        #bdae93;
        --fds-gray-100:       #d5c4a1;
        --fds-dark-mode-gray-35:  #504945;
        --fds-dark-mode-gray-50:  #665c54;
        --fds-dark-mode-gray-70:  #7c6f64;
        --fds-dark-mode-gray-80:  #928374;
        --fds-dark-mode-gray-90:  #a89984;
        --fds-dark-mode-gray-100: #bdae93;

        --fds-blue-05:  #0d1a1b;
        --fds-blue-30:  #2a4a4d;
        --fds-blue-40:  #3d6b6f;
        --fds-blue-60:  #83a598;
        --fds-blue-70:  #a0bdb7;
        --fds-blue-80:  #b8d0cb;
        --fds-green-55: #b8bb26;
        --fds-red-55:   #fb4934;
        --fds-yellow-20: #3a2e00;

        --fds-button-text:          #ebdbb2;
        --fds-comment-background:   #3c3836;
        --fds-highlight:            rgba(131, 165, 152, 0.25);
        --fds-highlight-cell-background: rgba(131, 165, 152, 0.1);
        --fds-soft:   cubic-bezier(.08,.52,.52,1);
        --fds-strong: cubic-bezier(.12,.8,.32,1);

        /* Core surface / interactive tokens */
        --accent:         #83a598;
        --always-white:   #fbf1c7;
        --always-black:   #1d2021;
        --always-dark-gradient: linear-gradient(rgba(29,32,33,0), rgba(29,32,33,0.7));
        --always-dark-overlay:  rgba(29, 32, 33, 0.5);
        --always-light-overlay: rgba(235, 219, 178, 0.3);
        --blue-link:      #83a598;

        --card-background:        #3c3836;   /* bg1 */
        --card-background-flat:   #504945;   /* bg2 */
        --comment-background:     #3c3836;
        --comment-footer-background: #504945;
        --surface-background:     #3c3836;
        --popover-background:     #32302f;
        --wash:                   #32302f;
        --web-wash:               #1d2021;

        --nav-bar-background: #282828;
        --nav-bar-background-gradient: linear-gradient(to top, #282828, rgba(40,40,40,.9), rgba(40,40,40,.7), rgba(40,40,40,.4), rgba(40,40,40,0));
        --nav-bar-background-gradient-wash: linear-gradient(to top, #1d2021, rgba(29,32,33,.9), rgba(29,32,33,.7), rgba(29,32,33,.4), rgba(29,32,33,0));

        --divider:          #3c3836;
        --hover-overlay:    rgba(235, 219, 178, 0.06);
        --press-overlay:    rgba(235, 219, 178, 0.06);
        --media-hover:      rgba(235, 219, 178, 0.06);
        --media-pressed:    rgba(235, 219, 178, 0.15);
        --media-inner-border: rgba(235, 219, 178, 0.04);
        --media-outer-border: #3c3836;
        --overlay-alpha-80: rgba(29, 32, 33, 0.80);
        --overlay-on-media: rgba(29, 32, 33, 0.65);

        --primary-text:         #ebdbb2;
        --primary-icon:         #ebdbb2;
        --secondary-text:       #bdae93;
        --secondary-icon:       #a89984;
        --section-header-text:  #d5c4a1;
        --placeholder-text:     #7c6f64;
        --placeholder-icon:     #7c6f64;
        --placeholder-image:    #504945;

        --primary-button-background:  #458588;   /* blue */
        --primary-button-pressed:     #83a598;   /* bright blue */
        --primary-button-text:        #fbf1c7;   /* fg0 */
        --secondary-button-background: rgba(235, 219, 178, 0.07);
        --secondary-button-text:       #ebdbb2;
        --disabled-button-background:  rgba(235, 219, 178, 0.12);
        --disabled-button-text:        rgba(235, 219, 178, 0.25);
        --disabled-icon:               rgba(235, 219, 178, 0.25);

        --toggle-active-background:  #458588;
        --toggle-active-icon:        #fbf1c7;
        --toggle-active-text:        #fbf1c7;

        --notification-badge:         #fb4934;
        --new-notification-background: #1d2021;
        --highlight-bg:   rgba(131, 165, 152, 0.2);
        --text-highlight: rgba(131, 165, 152, 0.35);

        --negative:            #fb4934;
        --negative-background: rgba(251, 73, 52, 0.15);
        --positive:            #b8bb26;
        --positive-background: rgba(184, 187, 38, 0.15);
        --warning:             #fabd2f;

        --scroll-thumb:  rgba(235, 219, 178, 0.2);
        --shadow-1: rgba(29, 32, 33, 0.3);
        --shadow-2: rgba(29, 32, 33, 0.5);
        --shadow-5: rgba(29, 32, 33, 0.7);
        --shadow-8: rgba(29, 32, 33, 0.9);
        --shadow-inset: rgba(235, 219, 178, 0.04);

        --grey-1: #3c3836;
        --grey-2: #504945;
        --grey-4: #665c54;
        --grey-5: #7c6f64;
        --grey-6: #928374;
        --grey-8: #bdae93;
        --grey-9: #d5c4a1;
        --blue-5: #83a598;

        /* Gruvbox data viz palette */
        --dataviz-primary-1:       rgb(131, 165, 152);  /* bright blue  */
        --dataviz-primary-2:       rgb(142, 192, 124);  /* bright aqua  */
        --dataviz-primary-3:       rgb(184, 187,  38);  /* bright green */
        --dataviz-secondary-1:     rgb(211, 134, 155);  /* bright purple */
        --dataviz-secondary-2:     rgb(177, 98,  134);  /* purple       */
        --dataviz-secondary-3:     rgb(251,  73,  52);  /* bright red   */
        --dataviz-supplementary-1: rgb(254, 128,  25);  /* bright orange */
        --dataviz-supplementary-2: rgb(250, 189,  47);  /* bright yellow */
        --dataviz-supplementary-3: rgb(104, 157, 106);  /* aqua         */
        --dataviz-supplementary-4: rgb(168, 153, 132);  /* fg4          */
    }


    /* ============================================================
    SECTION 3: LOGO IMAGES ONLY
    filter:invert() only on known leaf <img> elements.
    Never on containers — no cascade into post images.
    ============================================================ */

    img[src*="rsrc.php"][src*="instagram"],
    img[src*="nppLrRDPwRh"],
    img[src*="Ma96NGMpx3k"],
    img[src*="hzSTybO4xnl"],
    img[src*="mRucGeWws8j"],
    img[src*="I7oK-BX_VXn"] {
        /* Invert then hue-rotate to land on gruvbox fg1 warm tone */
        filter: invert(0.88) hue-rotate(180deg) sepia(0.15);
    }

    img[src*="ShFi4iY4Fd9.gif"] {
        filter: invert(0.88) hue-rotate(180deg) sepia(0.2) saturate(2);
    }


    /* ============================================================
    SECTION 4: BASE ELEMENT RESETS
    ============================================================ */

    body {
        background-color: #282828 !important;   /* bg0 */
        color: #ebdbb2 !important;               /* fg1 */
    }

    hr {
        background-color: #3c3836;               /* bg1 */
        border: none;
    }

    label {
        color: #a89984;                          /* fg4 */
    }

    option {
        background-color: #282828;
        color: #ebdbb2 !important;
    }

    /* Scrollbar */
    * {
        scrollbar-color: #504945 #1d2021;        /* bg2 thumb, bg0_h track */
        scrollbar-width: thin;
    }


    /* ============================================================
    SECTION 5: BLOKS / INLINE-STYLE OVERRIDES
    ============================================================ */

    div[data-bloks-name="bk.components.Flexbox"][style*="background: rgb(255, 255, 255)"],
    div[data-bloks-name="bk.components.Flexbox"][style*="background: rgb(250, 250, 250)"] {
        background-color: #282828 !important;
    }

    div[data-bloks-name="bk.components.Flexbox"][style*="background: rgb(219, 219, 219)"] {
        background-color: #3c3836 !important;
    }

    div[data-bloks-name="bk.components.Flexbox"][role="button"][style*="border: 1px solid rgb(219, 219, 219)"] {
        background-color: #282828 !important;
        border-color: #504945 !important;
    }

    [data-bloks-name="bk.components.Text"][style*="color: rgb(38, 38, 38)"],
    [data-bloks-name="bk.components.TextSpan"][style*="color: rgb(38, 38, 38)"] {
        color: #ebdbb2 !important;
    }

    [data-bloks-name="bk.components.TextSpan"][style*="color: rgb(0, 55, 107)"] {
        color: #83a598 !important;
    }

    [style*="background: rgb(38, 38, 38)"] {
        background-color: #3c3836 !important;
    }

    [style*="color: #999"] {
        color: #928374 !important;
    }


    /* ============================================================
    SECTION 6: MODAL / DIALOG
    ============================================================ */

    [role="dialog"]:not(div[class="x5yr21d x1o0tod x10l6tqk x13vifvy xh8yej3"]):not(div[class="x1ja2u2z x1afcbsf x1a2a7pz x6ikm8r x10wlt62 xdt5ytf xl56j7k x1n2onr6 x6s0dn4 x78zum5 x5yr21d xdj266r x14z9mp xat24cr x1lziwak x47corl xh8yej3"]){
        border-radius: 12px;
        border: 1px solid #504945;               /* bg2 */
    }

    [role="dialog"] [role="button"]:hover,
    [role="dialog"] a:hover {
        background: rgba(235, 219, 178, 0.06) !important;
        border-radius: 12px;
        transition: background 0.2s ease;
    }


    /* ============================================================
    SECTION 7: STORY RING — GRUVBOX GRADIENT
    Using gruvbox orange→yellow instead of the default blue/purple.
    ============================================================ */

    [class*="story"] > [class*="ring"]::before,
    [class*="highlight"] > [class*="ring"]::before {
        background-image: linear-gradient(45deg, #d65d0e, #fabd2f) !important;
    }


    /* ============================================================
    SECTION 8: FEED LAYOUT
    ============================================================ */

    ._9-ta {
        display: none !important;
    }

    [class*="feed"] {
        max-width: calc(470px + /*[[feed]]*/);
        margin: 0 auto;
    }


    /* ============================================================
    SECTION 9: DM / CHAT
    ============================================================ */

    [placeholder="Message..."],
    [aria-label="Message"] {
        background-color: #3c3836 !important;
        color: #ebdbb2 !important;
        border-color: #504945 !important;
    }


    /* ============================================================
