    [role="dialog"] > [style*="background-color: rgb(0, 0, 0)"],
    [role="dialog"] > [style*="background: rgb(0, 0, 0)"],
    [role="presentation"]:not(div[class="html-div xdj266r x14z9mp xat24cr x1lziwak x14ctfv x13sv91t x6ikm8r x10wlt62 xerhiuh x1pn3fxy x10zy8in xm9bcq3 x1n2onr6 x1vjfegm x1k4qllp x1mzt3pk x88qbow x1jm4cbz x114wg8e xrrpcnn x14rx4xb x13fuv20 x18b5jzi x1q0q8m5 x1t7ytsu x19livfd x1h2krnu x3p3xfz xet2kk3 xaymx6s x1lu5o8o x1ou5ly4 xofb2d2"]) > [style*="background-color: rgb(0, 0, 0)"],
