    div[class="x78zum5 xdt5ytf x1q2y9iw x1n2onr6 xh8yej3 x9f619 x1iyjqo2 x13lttk3 x1t7ytsu xpilrb4 xexx8yu xyri2b x18d9i69 x1c1uobl x1b5io7h"]{
        background: #282828 !important;
    }

    /* The horizontal band above and below a portrait video
    (letterbox bars that Instagram renders as separate divs) */
    [style*="background-color: rgb(0, 0, 0)"]:not(body):not(html):not(video):not(canvas):not(img) {
        background-color: #1d2021 !important;   /* bg0_h */
    }

    /* Catch-all for any element with hardcoded white bg in post context */
    [style*="background-color: rgb(255, 255, 255)"]:not(img):not(canvas):not(video) {
        background-color: #282828 !important;
    }
    [style*="background-color: rgb(250, 250, 250)"]:not(img):not(canvas):not(video) {
        background-color: #282828 !important;
    }


    /* ============================================================
    SECTION 11: AVATAR / PROFILE PICTURE PLACEHOLDERS
    Default grey SVG placeholder avatars should use gruvbox bg2
    so they don't look like the default Instagram grey on dark bg.
    ============================================================ */

    /* SVG circle fill used in default avatar placeholder */
    svg circle[fill="#DBDBDB"],
    svg circle[fill="#dbdbdb"],
    svg circle[fill="#efefef"],
    svg circle[fill="#EFEFEF"] {
        fill: #504945 !important;               /* bg2 */
    }

    /* SVG person silhouette fill in placeholder */
    svg path[fill="#FFFFFF"],
    svg path[fill="#ffffff"] {
        fill: #a89984 !important;               /* fg4 — warm muted */
    }

    /* Placeholder avatar <img> with broken/default src */
    img[src*="avatar_placeholder"],
    img[src*="default_avatar"],
    img[src*="placeholder"] {
        filter: sepia(0.4) saturate(0.6) brightness(0.7);
    }


    /* ============================================================
    SECTION 12: EMBEDDED VIDEO THUMBNAILS (YouTube / external)
    The YouTube play button icon appears as an <img> or inline SVG
    inside a video embed preview. We tint it gruvbox yellow.
    We target only the play button overlay, NOT the thumbnail img.
    ============================================================ */

    /* YouTube play button rendered as an img leaf node */
    img[src*="play"],
    img[alt*="Play"],
    img[aria-label*="Play"] {
        filter: sepia(1) saturate(3) hue-rotate(5deg) brightness(1.1);
        /* Result: warm gruvbox yellow #fabd2f tint */
    }

    /* Play button rendered as an inline SVG icon
    (safe: SVG icons have no img children, no cascade risk) */
    [aria-label="Play"] svg,
    [aria-label="Play video"] svg,
    button[aria-label*="Play"] svg {
        color: #fabd2f !important;              /* bright yellow */
        fill: #fabd2f !important;
    }

    /* DM panel — video embed container background */
    [class*="DirectThread"] [class*="video"],
    [class*="dm"] [class*="video-preview"],
    [class*="message"] [class*="media-preview"] {
        background-color: #1d2021 !important;   /* bg0_h */
        border-radius: 8px;
    }

    /* DM panel outer shell */
    [class*="DirectThread"],
    [class*="DirectInbox"] {
        background-color: #32302f !important;   /* bg0_s */
    }

    /* DM panel header */
    [class*="DirectThread"] header,
    [class*="DirectThread"] [role="banner"] {
        background-color: #282828 !important;   /* bg0 */
        border-bottom: 1px solid #3c3836 !important;   /* bg1 */
    }

    /* DM message bubbles — sent (own) messages */
    [class*="DirectThread"] [class*="own"] [class*="bubble"],
    [class*="DirectThread"] [class*="sent"] [class*="bubble"] {
        background-color: #458588 !important;   /* gruvbox blue */
        color: #fbf1c7 !important;              /* fg0 */
    }

    /* DM message bubbles — received messages */
    [class*="DirectThread"] [class*="received"] [class*="bubble"],
    [class*="DirectThread"] [class*="other"] [class*="bubble"] {
        background-color: #3c3836 !important;   /* bg1 */
        color: #ebdbb2 !important;              /* fg1 */
    }

    /* "X replied to themself" / thread reply label text */
    [class*="DirectThread"] [class*="reply"] [class*="label"],
    [class*="DirectThread"] [class*="thread"] > span {
        color: #a89984 !important;              /* fg4 */
    }

    /* Reply quote bar (the vertical left border on quoted messages) */
    [class*="DirectThread"] [class*="reply"]::before {
        background-color: #83a598 !important;   /* bright blue */
    }

