@var checkbox hideGroupsChats       "|- Hide Group Chats" 1

==/UserStyle== */

@-moz-document url-prefix("https://www.facebook.com/") {

    /* Disable animation */
    if animations {
        * {
            animation: none !important;
            transition: none !important;
        }
    }

    [class="AdBox Ad advert post-ads"],
    [class="sponsorPost"],
    [id="has-finished-comet-page"]{
        display: none;
    }

    if wide{ 
        div[role="main"] > div:first-child,
        div[role="main"] > div:first-child > div:first-child > div:first-child > div,
        div[role="main"] > div:first-child > div:first-child > div:first-child > div > div:first-child {
            width: 100% !important;
            max-width: none !important;
        }
        if hidefeed {
            div[class="x78zum5 xdt5ytf"]:has(div[aria-label="stories tray"]){                                   
                position: fixed;
                top: 45%;
                width: 96.3% !important;
            }
        } else {                                   
            div[class="x78zum5 xdt5ytf"]:has(div[aria-label="stories tray"]){                                   
                position: static !important;
                width: 205% !important;
                max-width: none !important;
            }            
        }                       
