* {
  font-family: 'JetBrains Mono', monospace !important;
  border-radius: 0 !important;
}

body, ytd-app {
  background: var(--bg-dark) !important;
  color: var(--text) !important;
}

/* bg remover 2000 */
ytd-watch-flexy,
#page-manager,
ytd-page-manager,
#primary,
#secondary,
#contents,
ytd-browse {
  background: transparent !important;
}

