.ytp-gradient-top,
.ytp-gradient-bottom,
ytd-watch-flexy[fullscreen] .ytp-gradient-top,
ytd-watch-flexy[fullscreen] .ytp-gradient-bottom,
.ytp-chrome-top,
#frosted-glass,
.ytp-chrome-bottom {
  background: none !important;
  backdrop-filter: none !important;
