}

    #voice-search-button {
        display: none !important;
    }

/* scrollbar hider 2000 - this kinda working... or not... */
::-webkit-scrollbar {
  display: none;
  width: 0px;
  height: 0px;
}

* {
  -ms-overflow-style: none; 
  scrollbar-width: none; 
}

/* scroillables */
body,
html,
ytd-app {
  overflow-y: auto !important;
  overflow-x: hidden !important;
}

/* top nav */
#masthead-container {
  position: fixed !important;
  top: 0px;
  left: 6px;
  right: 6px;
  z-index: 2020;
  background: var(--bg-dark) !important;
  padding: 10px 90px 18px 4px !important;
  margin: 0 !important;
  height: 45px !important;
  max-width: calc(100vw - 22px);
}

ytd-masthead {
  background: var(--bg-dark) !important;
  border: var(--border) solid var(--inactive) !important;
  transition: border-color 0.2s ease;
  position: relative;
  padding: 0px 0px 0px 0px !important;
  max-height: 60px;
  width: 100%;
}

ytd-masthead::before {
  content: 'ナビ';
  position: absolute;
  top: -10px;
  left: 8px;
  background: var(--bg-dark) !important;
  padding: 0 8px;
  font-size: 13px;
  font-weight: 700;
  color: var(--inactive);
  transition: color 0.2s ease;
  z-index: 10;
}

ytd-masthead:hover {
  border: var(--border) solid var(--active) !important;
}

ytd-masthead:hover::before {
  color: var(--active);
}

/* top padding & border fixer */
ytd-page-manager {
  margin-top: 82px !important;
  margin-left: -16px !important;
  margin-right: 3px !important;
}

